boltOn.example:
t3template.addControl({ id: 'punch', label: 'Punch', type: 'slider', min: 0, max: 100, step: 1, default: 40, panel: 'Finish' });
t3template.addControl({ id: 'fades', label: 'Clip Fades s', type: 'slider', min: 0, max: 2, step: 0.1, default: 0, panel: 'Finish' });
t3template.addControl({ id: 'title', label: 'Title', type: 'text', default: 'Sonoma', panel: 'Finish' });
t3template.addControl({ id: 'titleSec', label: 'Title (s)', type: 'slider', min: 0, max: 6, step: 0.5, default: 2.5, panel: 'Finish' });
t3template.addControl({ id: 'lowcut', label: 'Low Cut Hz', type: 'slider', min: 20, max: 300, step: 5, default: 80, panel: 'Finish' });
// Sound: heard while the monitor plays and rendered by ffmpeg on the mixed track.
t3template.addAudioFilter('lowcut', (c) => ({ type: 'highpass', frequency: c.lowcut }));
const look = (c) => t3template.grade({ contrast: c.punch * 0.3, saturation: c.punch * 0.5 });
// Fade each clip in and out: the preview dims near clip edges, the export uses ffmpeg fade with timeline enable.
t3template.addPreviewFilter((c, { time, clip }) => {
  if (!clip || !c.fades) return look(c).css;
  const edge = Math.min(time - clip.start, clip.start + clip.duration - time);
  return `${look(c).css} brightness(${Math.min(1, Math.max(0, edge / c.fades)).toFixed(3)})`;
});
t3template.addExportNote((edl, c) => {
  const fades = c.fades ? edl.tracks[0].clips.flatMap((k) => {
    const end = k.start + k.duration;
    return [`fade=t=in:st=${k.start}:d=${c.fades}:enable='between(t,${k.start},${k.start + c.fades})'`,
      `fade=t=out:st=${end - c.fades}:d=${c.fades}:enable='between(t,${end - c.fades},${end})'`];
  }) : [];
  return { videoFilter: [look(c).ffmpeg, ...fades].filter(Boolean).join(','), note: `Finish: punch ${c.punch}, clip fades ${c.fades} s` };
});
// Title card: drawn once at the picture size, shown over the first titleSec seconds on the monitor and in the render.
t3template.addOverlay('title', ({ context, width, height }, c) => {
  context.fillStyle = 'rgba(0, 0, 0, 0.55)';
  context.fillRect(0, height * 0.4, width, height * 0.2);
  context.fillStyle = '#ffffff';
  context.font = `600 ${Math.round(height * 0.09)}px sans-serif`;
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.fillText(c.title, width / 2, height / 2);
}, (c) => (c.title && c.titleSec ? { start: 0, end: c.titleSec } : null));
t3template.addToolbarButton('Mark Beat', (t) => {
  const v = t.getValues();
  t.setValues({ markers: [...v.markers, { time: v.playhead, label: 'Beat' }] }, 'Mark Beat');
}, { shortcut: 'b' });
